  "Research Plan:\n" + $json.research_plan +
  "\n\nRetrieved Evidence from the selected PDF:\n" +
  $json.retrieved_evidence
}}

parameters.jsCode:
return $input.all().map(item => {
  const message = item.json.chatInput || "";

  const documentMatch = message.match(/Document:\s*(.+)/i);
  const questionMatch = message.match(/Question:\s*([\s\S]+)/i);

  return {
    json: {
      ...item.json,
      document_title: documentMatch
        ? documentMatch[1].trim()
        : "",
      chatInput: questionMatch
        ? questionMatch[1].trim()
        : message.trim()
    }
  };
});

const documents = $input.all();

const researchPlan = $('Research Coordinator Agent').first().json.output;

const evidence = documents.map((item, index) => {
  const doc = item.json.document || item.json;

  return {
    section: index + 1,
    content: doc.pageContent || doc.content || "",
    metadata: doc.metadata || {},
    score: item.json.score ?? null
  };
});

return [{
  json: {
    research_plan: researchPlan,
    retrieved_evidence: JSON.stringify(evidence, null, 2)
  }
}];
